PRAGMA foreign_keys=ON;
PRAGMA user_version=2100;
BEGIN IMMEDIATE;
CREATE TABLE group_projection_store_binding(singleton_id INTEGER PRIMARY KEY CHECK(singleton_id=1),schema_version INTEGER NOT NULL CHECK(schema_version=2100),context_binding_fingerprint TEXT NOT NULL CHECK(length(context_binding_fingerprint)=64),created_at_utc TEXT NOT NULL) STRICT;
CREATE TABLE group_projection_job(job_id TEXT PRIMARY KEY CHECK(job_id LIKE 'gpj_%'),job_ref TEXT NOT NULL UNIQUE CHECK(job_ref LIKE 'gjb_%'),request_ref TEXT NOT NULL UNIQUE CHECK(request_ref LIKE 'req_%'),fifo_portfolio_ref TEXT NOT NULL CHECK(fifo_portfolio_ref LIKE 'pfr_%'),grouping_portfolio_ref TEXT NOT NULL CHECK(grouping_portfolio_ref LIKE 'xpf_%'),scheme_ref TEXT,grouping_revision_fingerprint TEXT NOT NULL CHECK(length(grouping_revision_fingerprint)=64),fifo_artifact_ref TEXT NOT NULL CHECK(fifo_artifact_ref LIKE 'rar_%'),event_tax_artifact_ref TEXT,annual_tax_artifact_ref TEXT,invalidated_by TEXT NOT NULL CHECK(invalidated_by IN ('initial','fifo','grouping','event_tax','annual_tax')),created_at_utc TEXT NOT NULL) STRICT;
CREATE TABLE group_projection_job_state(job_state_id TEXT PRIMARY KEY CHECK(job_state_id LIKE 'gjs_%'),job_id TEXT NOT NULL REFERENCES group_projection_job(job_id),state_sequence INTEGER NOT NULL,status TEXT NOT NULL CHECK(status IN ('pending','running','failed','completed')),failure_code TEXT,artifact_id TEXT,supersedes_job_state_id TEXT UNIQUE REFERENCES group_projection_job_state(job_state_id),created_at_utc TEXT NOT NULL,UNIQUE(job_id,state_sequence)) STRICT;
CREATE TABLE group_projection_artifact(artifact_id TEXT PRIMARY KEY CHECK(artifact_id LIKE 'gpa_%'),artifact_ref TEXT NOT NULL UNIQUE CHECK(artifact_ref LIKE 'gpr_%'),fifo_portfolio_ref TEXT NOT NULL,grouping_portfolio_ref TEXT NOT NULL,scheme_ref TEXT,scheme_type TEXT NOT NULL CHECK(scheme_type IN ('none','exclusive_hierarchy','tag_set')),grouping_revision_fingerprint TEXT NOT NULL,fifo_artifact_ref TEXT NOT NULL,event_tax_artifact_ref TEXT,annual_tax_artifact_ref TEXT,algorithm_version TEXT NOT NULL,rebuild_mode TEXT NOT NULL CHECK(rebuild_mode IN ('full','incremental')),base_artifact_id TEXT REFERENCES group_projection_artifact(artifact_id),source_job_id TEXT NOT NULL UNIQUE REFERENCES group_projection_job(job_id),row_set_fingerprint TEXT NOT NULL,semantic_source_bindings_json TEXT NOT NULL CHECK(json_valid(semantic_source_bindings_json)),semantic_binding_fingerprint TEXT NOT NULL CHECK(length(semantic_binding_fingerprint)=64),coverage_status TEXT NOT NULL CHECK(coverage_status IN ('complete','unassigned','not_applicable')),currency_status TEXT NOT NULL CHECK(currency_status IN ('single_currency','native_currency_slices','empty')),completed_at_utc TEXT NOT NULL,CHECK((rebuild_mode='full' AND base_artifact_id IS NULL) OR (rebuild_mode='incremental' AND base_artifact_id IS NOT NULL))) STRICT;
CREATE TABLE group_projection_row_blob(row_blob_id TEXT PRIMARY KEY CHECK(row_blob_id LIKE 'grb_%'),row_fingerprint TEXT NOT NULL UNIQUE,table_name TEXT NOT NULL CHECK(table_name IN ('group-metrics.csv','group-drilldown.csv','group-reconciliation.csv','group-annual-tax.csv')),row_json TEXT NOT NULL CHECK(json_valid(row_json)),created_at_utc TEXT NOT NULL) STRICT;
CREATE TABLE group_projection_artifact_row(artifact_id TEXT NOT NULL REFERENCES group_projection_artifact(artifact_id),table_name TEXT NOT NULL,row_ordinal INTEGER NOT NULL,row_blob_id TEXT NOT NULL REFERENCES group_projection_row_blob(row_blob_id),PRIMARY KEY(artifact_id,table_name,row_ordinal)) STRICT,WITHOUT ROWID;
CREATE VIEW current_group_projection_job_state AS SELECT state.* FROM group_projection_job_state state WHERE NOT EXISTS(SELECT 1 FROM group_projection_job_state successor WHERE successor.supersedes_job_state_id=state.job_state_id);
CREATE TRIGGER group_projection_state_chain BEFORE INSERT ON group_projection_job_state BEGIN SELECT CASE WHEN NEW.state_sequence=1 AND (NEW.status!='pending' OR NEW.supersedes_job_state_id IS NOT NULL) THEN RAISE(ABORT,'group_projection_state_initial_invalid') END;SELECT CASE WHEN NEW.state_sequence>1 AND NOT EXISTS(SELECT 1 FROM current_group_projection_job_state old WHERE old.job_state_id=NEW.supersedes_job_state_id AND old.job_id=NEW.job_id AND old.state_sequence+1=NEW.state_sequence) THEN RAISE(ABORT,'group_projection_state_chain_invalid') END;END;
CREATE TRIGGER group_projection_binding_no_update BEFORE UPDATE ON group_projection_store_binding BEGIN SELECT RAISE(ABORT,'group_projection_immutable'); END;
CREATE TRIGGER group_projection_binding_no_delete BEFORE DELETE ON group_projection_store_binding BEGIN SELECT RAISE(ABORT,'group_projection_immutable'); END;
CREATE TRIGGER group_projection_job_no_update BEFORE UPDATE ON group_projection_job BEGIN SELECT RAISE(ABORT,'group_projection_immutable'); END;
CREATE TRIGGER group_projection_job_no_delete BEFORE DELETE ON group_projection_job BEGIN SELECT RAISE(ABORT,'group_projection_immutable'); END;
CREATE TRIGGER group_projection_state_no_update BEFORE UPDATE ON group_projection_job_state BEGIN SELECT RAISE(ABORT,'group_projection_immutable'); END;
CREATE TRIGGER group_projection_state_no_delete BEFORE DELETE ON group_projection_job_state BEGIN SELECT RAISE(ABORT,'group_projection_immutable'); END;
CREATE TRIGGER group_projection_artifact_no_update BEFORE UPDATE ON group_projection_artifact BEGIN SELECT RAISE(ABORT,'group_projection_immutable'); END;
CREATE TRIGGER group_projection_artifact_no_delete BEFORE DELETE ON group_projection_artifact BEGIN SELECT RAISE(ABORT,'group_projection_immutable'); END;
CREATE TRIGGER group_projection_blob_no_update BEFORE UPDATE ON group_projection_row_blob BEGIN SELECT RAISE(ABORT,'group_projection_immutable'); END;
CREATE TRIGGER group_projection_blob_no_delete BEFORE DELETE ON group_projection_row_blob BEGIN SELECT RAISE(ABORT,'group_projection_immutable'); END;
CREATE TRIGGER group_projection_row_no_update BEFORE UPDATE ON group_projection_artifact_row BEGIN SELECT RAISE(ABORT,'group_projection_immutable'); END;
CREATE TRIGGER group_projection_row_no_delete BEFORE DELETE ON group_projection_artifact_row BEGIN SELECT RAISE(ABORT,'group_projection_immutable'); END;
COMMIT;
